import math

def solve(h,w_kn,T):
 def depth(H):
  if H<=0 or H>=T: return 0.0
  V=math.sqrt(max(0,T*T-H*H))
  ratio=V/H
  if ratio>50: return float('inf')
  return H/w_kn*(math.cosh(ratio)-1)
 low=max(T*1e-12,1e-9); high=T*(1-1e-12)
 for _ in range(120):
  mid=(low+high)/2
  hc=depth(mid)
  if abs(hc-h)<.01:
   low=high=mid; break
  if not math.isfinite(hc) or hc>h:
   low=mid
  else:
   high=mid
 H=(low+high)/2
 a=H/w_kn
 x=a*math.acosh(1+h/a)
 s=a*math.sinh(x/a)
 Vtop=w_kn*s
 Ttop=math.sqrt(H*H+Vtop*Vtop)
 return H, s, Vtop, Ttop
for T in [100,200,300,400,500,1000,5000]:
 print(T, solve(200,.8,T))
